'use strict';
const dimensions=['Integração','Qualidade','Indicadores','Decisões','Automação & IA'];
const questions=[
 {d:0,q:'Onde estão os dados da sua empresa hoje?',hint:'Pense nas informações de vendas, financeiro e operação.',a:['Espalhados em planilhas e sistemas que não conversam.','Reunidos manualmente quando precisamos de uma análise.','As principais fontes estão conectadas, com algumas lacunas.','Integrados em uma base central, com atualização automática.']},
 {d:0,q:'Como vocês combinam informações de áreas diferentes?',hint:'Por exemplo: relacionar vendas, custos e margem.',a:['Não conseguimos cruzar essas informações.','Alguém junta arquivos e faz os cruzamentos manualmente.','Temos cruzamentos recorrentes, mas algumas áreas ficam de fora.','As áreas usam uma visão integrada, com definições em comum.']},
 {d:1,q:'Quanto a equipe confia nos números que recebe?',hint:'Considere divergências, duplicidades e dados desatualizados.',a:['É comum encontrar números diferentes para a mesma informação.','Precisamos conferir e corrigir os dados antes de usar.','Os principais dados são validados, com problemas pontuais.','Há validação contínua, responsáveis e regras de qualidade.']},
 {d:1,q:'Existe uma organização clara para cuidar dos dados?',hint:'Pense em responsáveis, definições de métricas e acesso.',a:['Não há responsáveis nem regras definidas.','Algumas pessoas cuidam disso, de maneira informal.','Há responsáveis e regras documentadas para os dados principais.','Responsabilidades, acessos e definições são revisados regularmente.']},
 {d:2,q:'Como vocês acompanham os indicadores do negócio?',hint:'Considere as métricas que a liderança usa no dia a dia.',a:['Decidimos sem acompanhar indicadores de forma recorrente.','Usamos planilhas e relatórios preparados manualmente.','Temos dashboards com os principais indicadores atualizados.','Acompanhamos indicadores integrados a metas, contexto e alertas.']},
 {d:2,q:'Quando um indicador muda, vocês conseguem entender por quê?',hint:'Por exemplo: uma queda nas vendas ou na margem.',a:['Normalmente não conseguimos encontrar a causa.','Precisamos pedir uma análise e esperar por respostas.','Conseguimos investigar por produto, canal, região ou período.','Identificamos os fatores da mudança e priorizamos ações rapidamente.']},
 {d:3,q:'Qual é o papel dos dados nas decisões da liderança?',hint:'Escolha o cenário mais comum, não o ideal.',a:['As decisões se apoiam principalmente na intuição.','Consultamos dados em algumas decisões importantes.','Os dados fazem parte das reuniões e das decisões recorrentes.','Decidimos com evidências e medimos o efeito de cada ação.']},
 {d:3,q:'A equipe consegue transformar uma análise em ação?',hint:'Pense em autonomia, entendimento e acompanhamento.',a:['As análises raramente chegam a quem precisa agir.','Dependemos de uma pessoa para explicar os números.','Os gestores entendem os indicadores e definem ações.','As áreas têm autonomia, responsáveis e acompanhamento dos resultados.']},
 {d:4,q:'Quanto do trabalho de análise é automatizado?',hint:'Considere coleta, atualização e distribuição dos relatórios.',a:['Quase tudo depende de copiar, colar e montar arquivos.','Automatizamos tarefas pontuais, mas o trabalho ainda é manual.','A coleta e os principais relatórios já são automatizados.','O fluxo é automatizado e avisa quando há falhas ou desvios.']},
 {d:4,q:'Como a empresa usa IA e análises preditivas?',hint:'Considere aplicações conectadas aos dados do seu negócio.',a:['Ainda não usamos IA ou previsões nas análises.','Estamos explorando ferramentas, sem uso recorrente.','Já usamos previsões ou IA em alguns processos.','Usamos IA com dados validados e acompanhamos a qualidade das previsões.']}
];
const recommendations=[
 {title:'Conecte o que hoje está separado.',action:'Mapeie as fontes de vendas, custos e operação. Comece conectando as que respondem à decisão mais importante do negócio.',service:'A TheDobra conecta ERP, CRM, planilhas e outras fontes em uma visão integrada.'},
 {title:'Crie uma base em que todos confiem.',action:'Defina responsáveis, padronize os principais indicadores e valide divergências antes de ampliar as análises.',service:'A TheDobra organiza os dados com modelo semântico, métricas e governança.'},
 {title:'Dê contexto aos seus indicadores.',action:'Escolha os indicadores prioritários, relacione-os às metas e detalhe os recortes necessários para investigar mudanças.',service:'A TheDobra reúne BI, KPIs e contexto para mostrar o que merece atenção.'},
 {title:'Leve os dados para a próxima decisão.',action:'Crie uma rotina de análise com responsáveis por cada ação e acompanhe o que mudou depois de cada decisão.',service:'A TheDobra entrega uma visão compartilhada para a liderança identificar onde agir primeiro.'},
 {title:'Libere tempo para interpretar.',action:'Automatize primeiro os relatórios repetitivos. Com uma base confiável, avance para alertas e previsões validadas.',service:'A TheDobra usa IA analítica para encontrar padrões, anomalias, oportunidades e riscos.'}
];
const levels=[{name:'Inicial',text:'O potencial está nos dados que vocês já têm. O primeiro passo é organizar a base e tornar os números acessíveis.'},{name:'Em estruturação',text:'Sua empresa já começou a usar dados. Agora, a oportunidade é reduzir o trabalho manual e criar uma visão consistente.'},{name:'Conectada',text:'Os dados já apoiam o negócio. O próximo passo é fechar as lacunas e transformar análises em ações mais rápidas.'},{name:'Orientada por dados',text:'Sua empresa relata práticas maduras. O foco pode avançar para refinar a governança, testar previsões e ampliar o impacto das análises.'}];
let index=0;let answers=Array(10).fill(undefined);let resultVisible=false;
const main=document.querySelector('main');
const clock='<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="10" cy="10" r="7.5"/><path d="M10 5v5l3 2"/></svg>';
function calculate(values){const known=values.filter(v=>Number.isInteger(v));const score=known.length?Math.round(known.reduce((a,b)=>a+b,0)/(known.length*3)*100):null;return {score,coverage:known.length,byDimension:dimensions.map((_,d)=>{const a=values.filter((v,i)=>questions[i].d===d&&Number.isInteger(v));return {d,score:a.length?Math.round(a.reduce((x,y)=>x+y,0)/(a.length*3)*100):null,count:a.length};})};}
function focusHeading(){main.querySelector('h1, h2')?.focus({preventScroll:true});}
function renderQuiz(focus=false){resultVisible=false;const q=questions[index];main.innerHTML=`<div class="layout"><section class="intro"><span class="eyebrow">DIAGNÓSTICO GRATUITO · DADOS & IA</span><h1>Sua empresa tem dados.<br>Mas tem <em>clareza?</em></h1><p>Descubra como sua empresa transforma dados em decisões — e o que falta para chegar ao próximo nível.</p><div class="meta"><span>${clock} Cerca de 3 minutos</span><span>✓ Sem cadastro</span></div><div class="dimensions"><span>5 DIMENSÕES. UMA VISÃO MAIS CLARA.</span><div class="dimension-list">${dimensions.map((d,i)=>`<span class="dimension ${i===q.d?'active':''}">${d}</span>`).join('')}</div></div><div class="insight"><span class="star" aria-hidden="true">✧</span><p><b>O próximo passo começa com um diagnóstico.</b><br>Ao final, receba seu nível de maturidade e prioridades para evoluir com a TheDobra.</p></div></section><section class="quiz-wrap" aria-label="Questionário de maturidade"><div class="quiz-card"><div class="card-top"><strong>Seu diagnóstico</strong><span><b>${String(index+1).padStart(2,'0')}</b> / 10 perguntas</span></div><div class="progress" role="progressbar" aria-label="Perguntas respondidas" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${answers.filter(v=>v!==undefined).length}"><div style="width:${answers.filter(v=>v!==undefined).length*10}%"></div></div><span class="category">${String(q.d+1).padStart(2,'0')} / ${dimensions[q.d].toUpperCase()}</span><h2 class="question" id="question" tabindex="-1">${q.q}</h2><p class="hint" id="hint">${q.hint}</p><fieldset class="options" aria-labelledby="question" aria-describedby="hint">${q.a.map((a,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${answers[index]===i?'checked':''}><span>${a}</span></label>`).join('')}<label class="unknown"><input type="radio" name="answer" value="unknown" ${answers[index]===null?'checked':''}>Não sei responder</label></fieldset><div class="actions"><button class="text-button" id="back" ${index===0?'disabled':''}>Voltar</button><button class="primary" id="next" ${answers[index]===undefined?'disabled':''}>${index===9?'Ver meu diagnóstico':'Continuar'}</button></div></div><p class="privacy"><span aria-hidden="true">◇</span> Respostas privadas. Nenhum dado da empresa é solicitado.</p></section></div><div class="below"><p>Menos achismo. Mais direção.<br>Entenda onde você está para saber onde agir.</p><div class="steps"><span><b>01</b> Responda</span><span><b>02</b> Descubra seu nível</span><span><b>03</b> Encontre seu próximo passo</span></div></div>`;
main.querySelectorAll('input').forEach(el=>el.addEventListener('change',()=>{answers[index]=el.value==='unknown'?null:Number(el.value);document.querySelector('#next').disabled=false;const count=answers.filter(v=>v!==undefined).length;const bar=main.querySelector('.progress');bar.setAttribute('aria-valuenow',count);bar.firstElementChild.style.width=count*10+'%';}));document.querySelector('#back').onclick=()=>{if(index>0){index--;renderQuiz(true)}};document.querySelector('#next').onclick=()=>{if(answers[index]===undefined)return;if(index<9){index++;renderQuiz(true)}else{renderResult()}};if(focus)main.querySelector('.question').focus({preventScroll:true});}
function renderResult(){resultVisible=true;const result=calculate(answers);const level=result.score===null?{name:'Diagnóstico inconclusivo',text:'Ainda não há respostas suficientes para identificar seu nível. Converse com quem acompanha os dados e revise o diagnóstico.'}:levels[Math.min(3,Math.floor(result.score/25))];const priorities=[...result.byDimension].sort((a,b)=>(a.score??-1)-(b.score??-1)||a.d-b.d).slice(0,3);main.innerHTML=`<section class="result"><div class="result-title"><div><span class="eyebrow">SEU RADAR DE MATURIDADE</span><h1 tabindex="-1">Clareza para o próximo passo.</h1><p>${level.text}</p></div></div><div class="result-grid"><div class="score-card"><span class="category">${result.coverage<10?'RESULTADO PARCIAL':'MATURIDADE EM DADOS'}</span><div class="score-number">${result.score??'—'} <small>/ 100</small></div><span class="level">${level.name}</span><p>${result.coverage} de 10 respostas pontuadas.${result.coverage<10?' As respostas “Não sei” não entram na nota. Complete as lacunas para uma visão mais precisa.':' Uma visão da sua empresa com base nas práticas que você informou.'}</p></div><div class="breakdown"><h2>Seu desempenho por dimensão</h2>${result.byDimension.map(d=>`<div class="metric"><div class="metric-label"><span>${dimensions[d.d]}${d.count===1?' · parcial':''}</span><span>${d.score===null?'Sem dados':d.score+' / 100'}</span></div><div class="metric-track"><div style="width:${d.score??0}%"></div></div></div>`).join('')}</div></div><section class="plan"><h2>${result.score===null?'Comece conhecendo sua operação.':'Onde vale agir primeiro.'}</h2><p>${result.coverage<10?'Primeiro, esclareça as dimensões sem dados. Depois, priorize as menores pontuações.':'Estas são as três dimensões com menor pontuação. Em caso de empate, começamos pela base: integração e qualidade.'}</p><div class="recommendations">${priorities.map((d,i)=>{const r=recommendations[d.d];return `<article class="recommendation"><span class="num">0${i+1} / ${dimensions[d.d].toUpperCase()}</span><h3>${d.score===null?'Entenda como a área funciona.':r.title}</h3><p>${d.score===null?'Converse com os responsáveis por '+dimensions[d.d].toLowerCase()+' para preencher as lacunas antes de definir um plano.':d.score>=75?'Sua base nesta dimensão é forte. Revise os processos, monitore a adoção e valide oportunidades de melhoria contínua.':r.action}</p><p class="service">${r.service}</p></article>`}).join('')}</div></section><section class="cta"><div><span class="eyebrow">O PRÓXIMO PASSO, COM A THEDOBRA</span><h2>Seus dados podem fazer mais pelo seu negócio.</h2><p>A TheDobra conecta as fontes que você já usa, organiza suas informações e combina BI e IA para identificar riscos, oportunidades e prioridades. Leve este diagnóstico para uma conversa sobre a sua empresa.</p></div><a class="primary" href="https://www.thedobra.cc/#contato" target="_blank" rel="noopener">Falar com um especialista</a></section><p class="note">Autoavaliação exploratória, sem validação independente. As recomendações não garantem resultados e dependem das fontes e necessidades da empresa.</p><div class="result-tools"><button class="text-button" id="review">Revisar respostas</button><button class="text-button" id="restart">Refazer diagnóstico</button><button class="text-button" id="print">Imprimir resultado</button></div></section>`;document.querySelector('#review').onclick=()=>{index=0;renderQuiz(true)};document.querySelector('#restart').onclick=()=>{answers=Array(10).fill(undefined);index=0;renderQuiz(true)};document.querySelector('#print').onclick=()=>window.print();window.scrollTo({top:0,behavior:'instant'});focusHeading();}
document.querySelector('#method').onclick=()=>document.querySelector('dialog').showModal();document.querySelector('.close').onclick=()=>document.querySelector('dialog').close();
renderQuiz();
